import sys
from collections import Counter
from math import sqrt

def prime_factors(n):
    factors = []
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    for i in range(3, int(sqrt(n)) + 1, 2):
        while n % i == 0:
            factors.append(i)
            n //= i
    if n > 2:
        factors.append(n)
    return factors

def min_divisor_tree_vertices(n, a):
    factor_counts = Counter()
    for num in a:
        factor_counts.update(prime_factors(num))
    return sum(factor_counts.values())

input = sys.stdin.read().split()
n = int(input[0])
a = list(map(int, input[1:]))
print(min_divisor_tree_vertices(n, a))
